import 'package:equatable/equatable.dart';

/// A flat, denormalized row representing a single product line within a sale.
/// Generated by a JOIN between `ventas`, `detalle_ventas`, and `products`.
class SalesHistoryEntry extends Equatable {
  final String ventaId;
  final DateTime fecha;
  final String metodoPago;
  final String tipoEntrega;
  final String? usuarioId;
  final String? clienteId;
  final String clienteNombre;

  final String detalleId;
  final String productId;
  final String productName;
  final String? sku;
  final int cantidad;
  final double costoUnitario;
  final double precioUnitario;
  final double lineDiscount;

  const SalesHistoryEntry({
    required this.ventaId,
    required this.fecha,
    required this.metodoPago,
    required this.tipoEntrega,
    this.usuarioId,
    this.clienteId,
    required this.clienteNombre,
    required this.detalleId,
    required this.productId,
    required this.productName,
    this.sku,
    required this.cantidad,
    required this.costoUnitario,
    required this.precioUnitario,
    this.lineDiscount = 0.0,
  });

  double get lineTotal => (precioUnitario * cantidad) - lineDiscount;
  double get totalCosto => costoUnitario * cantidad;
  double get ganancia => lineTotal - totalCosto;
  double get margenPct => lineTotal > 0 ? (ganancia / lineTotal) * 100 : 0.0;

  @override
  List<Object?> get props => [
        ventaId,
        fecha,
        metodoPago,
        tipoEntrega,
        usuarioId,
        clienteId,
        clienteNombre,
        detalleId,
        productId,
        productName,
        sku,
        cantidad,
        costoUnitario,
        precioUnitario,
        lineDiscount,
      ];
}
